@namespace sv_5e60acf715bd444f96a38f113d50b44a.Components.Pages.Settings
@using sv_5e60acf715bd444f96a38f113d50b44a.Services

<div class="card mb-3">
    <div class="card-header"><h5 class="mb-0">Security Settings</h5></div>
    <div class="card-body">
        <ChangePasswordPanel OnChangePassword="OnChangePassword" />

        <div class="card mb-3">
            <div class="card-body">
                <div class="d-flex justify-content-between align-items-center">
                    <div>
                        <h6 class="mb-1">Two-Factor Authentication</h6>
                        <p class="text-muted mb-0 small">
                            @if (Settings?.TwoFactorEnabled == true)
                            {
                                <span class="badge bg-success me-1">Enabled</span>
                                <text>Your account is protected with 2FA.</text>
                            }
                            else
                            {
                                <span class="badge bg-warning me-1">Disabled</span>
                                <text>Enable 2FA for additional security.</text>
                            }
                        </p>
                    </div>
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="twoFaToggle"
                               checked="@(Settings?.TwoFactorEnabled ?? false)"
                               disabled />
                    </div>
                </div>
                @if (Settings?.LastPasswordChange is not null)
                {
                    <p class="text-muted small mt-2 mb-0">Last password change: @Settings.LastPasswordChange.Value.ToString("f")</p>
                }
            </div>
        </div>

        <ActiveSessionsTable Sessions="@Settings?.Sessions"
                             CurrentSessionId="@(Settings?.Sessions?.FirstOrDefault()?.Id)"
                             OnRevoke="OnRevoke" />
    </div>
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<(string Current, string New)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<string> OnRevoke { get; set; }
}

@namespace sv_5e60acf715bd444f96a38f113d50b44a.Components.Pages.Settings

<div class="card">
    <div class="card-header"><h6 class="mb-0">Preview</h6></div>
    <div class="card-body @_bgClass" style="@_style min-height: 120px; transition: all 0.3s;">
        <h6 class="@_textClass" style="@_fontStyle">Sample Heading</h6>
        <p class="@_textClass" style="@_fontStyle">
            This is a preview of how your content will look with the selected appearance settings.
        </p>
        <button class="btn btn-sm @_btnClass">Sample Button</button>
    </div>
</div>

@code {
    [Parameter] public string Theme { get; set; } = "Light";
    [Parameter] public string FontSize { get; set; } = "Medium";
    [Parameter] public bool CompactMode { get; set; }

    private string _bgClass => Theme switch
    {
        "Dark" => "bg-dark",
        "System" => "bg-secondary bg-opacity-10",
        _ => "bg-light"
    };

    private string _textClass => Theme == "Dark" ? "text-light" : "text-dark";
    private string _btnClass => Theme == "Dark" ? "btn-light" : "btn-primary";

    private string _fontStyle => FontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.2rem;",
        _ => "font-size: 1rem;"
    };

    private string _style => CompactMode ? "padding: 0.5rem !important;" : "";
}

@namespace sv_5e60acf715bd444f96a38f113d50b44a.Components.Pages.Settings
@using sv_5e60acf715bd444f96a38f113d50b44a.Services

<div class="card">
    <div class="card-header"><h5 class="mb-0">Appearance Settings</h5></div>
    <div class="card-body">
        @if (_successMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_successMessage
                <button type="button" class="btn-close" @onclick="() => _successMessage = null"></button>
            </div>
        }

        <div class="row">
            <div class="col-md-6">
                <div class="mb-3">
                    <label class="form-label fw-bold">Theme</label>
                    <div>
                        @foreach (var theme in new[] { "Light", "Dark", "System" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="theme"
                                       id="@($"theme-{theme}")" value="@theme"
                                       checked="@(_theme == theme)"
                                       @onchange="() => _theme = theme" />
                                <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Font Size</label>
                    <div>
                        @foreach (var size in new[] { "Small", "Medium", "Large" })
                        {
                            <div class="form-check">
                                <input class="form-check-input" type="radio" name="fontSize"
                                       id="@($"fs-{size}")" value="@size"
                                       checked="@(_fontSize == size)"
                                       @onchange="() => _fontSize = size" />
                                <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                            </div>
                        }
                    </div>
                </div>

                <div class="mb-3">
                    <label class="form-label fw-bold">Language</label>
                    <select class="form-select" @bind="_language">
                        <option value="en">English</option>
                        <option value="es">Español</option>
                        <option value="fr">Français</option>
                        <option value="de">Deutsch</option>
                        <option value="ja">日本語</option>
                    </select>
                </div>

                <div class="mb-3">
                    <div class="form-check form-switch">
                        <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                        <label class="form-check-label" for="compactMode">Compact Mode</label>
                    </div>
                </div>

                <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
                    @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Save
                </button>
            </div>
            <div class="col-md-6">
                <AppearancePreview Theme="@_theme" FontSize="@_fontSize" CompactMode="@_compactMode" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "en";
    private bool _compactMode;
    private bool _saving;
    private string? _successMessage;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_saving)
        {
            _theme = Settings.Theme;
            _fontSize = Settings.FontSize;
            _language = Settings.Language;
            _compactMode = Settings.CompactMode;
        }
    }

    private async Task SaveAsync()
    {
        _saving = true;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await OnSave.InvokeAsync(updated);
        _saving = false;
        _successMessage = "Appearance settings saved!";
    }
}

@page "/settings"
@namespace sv_5e60acf715bd444f96a38f113d50b44a.Components.Pages.Settings
@using sv_5e60acf715bd444f96a38f113d50b44a.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h3 class="mb-4">Settings</h3>

    <div class="row">
        <div class="col-md-3 col-lg-2 mb-3">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="section => _activeSection = section" />
        </div>
        <div class="col-md-9 col-lg-10">
            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                </div>
            }
            else
            {
                @switch (_activeSection)
                {
                    case "Profile":
                        <ProfileSection Profile="@_profile" OnSave="SaveProfileAsync" />
                        break;
                    case "Notifications":
                        <NotificationsSection Prefs="@_notificationPrefs" OnSave="SaveNotificationsAsync" />
                        break;
                    case "Security":
                        <SecuritySection Settings="@_securitySettings"
                                         OnChangePassword="ChangePasswordAsync"
                                         OnRevoke="RevokeSessionAsync" />
                        break;
                    case "Appearance":
                        <AppearanceSection Settings="@_appearanceSettings" OnSave="SaveAppearanceAsync" />
                        break;
                }
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";
    private bool _loading = true;

    private UserProfile? _profile;
    private NotificationPrefs? _notificationPrefs;
    private SecuritySettings? _securitySettings;
    private AppearanceSettings? _appearanceSettings;

    protected override async Task OnInitializedAsync()
    {
        await LoadAllAsync();
        _loading = false;
    }

    private async Task LoadAllAsync()
    {
        var profileTask = SettingsService.GetProfileAsync();
        var notifTask = SettingsService.GetNotificationPrefsAsync();
        var securityTask = SettingsService.GetSecuritySettingsAsync();
        var appearanceTask = SettingsService.GetAppearanceAsync();

        await Task.WhenAll(profileTask, notifTask, securityTask, appearanceTask);

        _profile = profileTask.Result;
        _notificationPrefs = notifTask.Result;
        _securitySettings = securityTask.Result;
        _appearanceSettings = appearanceTask.Result;
    }

    private async Task SaveProfileAsync(UserProfile profile)
    {
        await SettingsService.SaveProfileAsync(profile);
        _profile = profile;
    }

    private async Task SaveNotificationsAsync(NotificationPrefs prefs)
    {
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        _notificationPrefs = prefs;
    }

    private async Task ChangePasswordAsync((string Current, string New) args)
    {
        await SettingsService.ChangePasswordAsync(args.Current, args.New);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task RevokeSessionAsync(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        _securitySettings = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearanceAsync(AppearanceSettings settings)
    {
        await SettingsService.SaveAppearanceAsync(settings);
        _appearanceSettings = settings;
    }
}

